// Ransom Note - Check if note can be constructed from magazine letters
var table = AnimatedHashTable<String, Int>()
let magazine = ["a", "b", "c", "a"]
let ransom = ["a", "a", "b"]

func canConstruct(_ ransom: [String], from magazine: [String], t: inout AnimatedHashTable<String, Int>) -> Bool {
    for char in magazine {
        let count = t.get(char) ?? 0
        t.put(char, count + 1)
    }
    for char in ransom {
        let count = t.get(char) ?? 0
        if count <= 0 {
            return false
        }
        t.put(char, count - 1)
    }
    return true
}

let possible = canConstruct(ransom, from: magazine, t: &table)
